//! The party (`p-` / `s-p-`) and classroom (`k-` / `s-k-`) wire protocols, mirroring the zod schemas in
//! `packages/shared/src/protocol/{party,classroom}.ts` — those stay the source of truth.
//!
//! `tests/protocol.rs` round-trips every variant of both schemas through these types from fixtures
//! GENERATED by `tools/engine-protocol.mjs` (`pnpm engine:protocol`, CI `--check`): a field added to
//! a zod schema and missing here fails that test, because it would be dropped on the way back.
//!
//! Names the server picks from a closed list (games, roles, animations, error codes…) stay plain
//! strings: a newer server may send a value this build does not know, and that must not drop the
//! whole message. The constants below name the values this build acts on.

use serde::de::{self, SeqAccess, Visitor};
use serde::ser::SerializeSeq;
use serde::{Deserialize, Deserializer, Serialize, Serializer};

/// `PARTY_PROTOCOL_VERSION` (party.ts). The fixtures carry the TypeScript value; a test compares.
pub const PARTY_PROTOCOL_VERSION: u32 = 1;
/// `CLASS_PROTOCOL_VERSION` (classroom.ts).
pub const CLASS_PROTOCOL_VERSION: u32 = 10;
/// Largest message the server sends (decodeClassServer's limit: whole-world batches).
pub const MAX_SERVER_MESSAGE: usize = 4 * 1024 * 1024;

pub mod game {
    pub const BUILD: &str = "build";
    pub const TOWER: &str = "tower";
}

// ------------------------------------------------------------------------------------------- party

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Seat {
    pub code: String,
    pub key: String,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "t", rename_all_fields = "camelCase")]
pub enum PartyClient {
    /// First message. `seat` re-takes a seat held from before.
    #[serde(rename = "p-hello")]
    Hello {
        v: u32,
        name: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        seat: Option<Seat>,
    },
    /// Start receiving the public room list and its updates.
    #[serde(rename = "p-list")]
    List,
    #[serde(rename = "p-create")]
    Create { title: String, game: String, max: u32, public: bool },
    #[serde(rename = "p-join")]
    Join { code: String },
    #[serde(rename = "p-quick")]
    Quick {
        #[serde(default, skip_serializing_if = "Option::is_none")]
        game: Option<String>,
    },
    #[serde(rename = "p-leave")]
    Leave,
    #[serde(rename = "p-ready")]
    Ready { ready: bool },
    #[serde(rename = "p-chat")]
    Chat { text: String },
    #[serde(rename = "p-set")]
    Set {
        #[serde(default, skip_serializing_if = "Option::is_none")]
        game: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        title: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        max: Option<u32>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        public: Option<bool>,
    },
    #[serde(rename = "p-start")]
    Start,
    #[serde(rename = "p-stop")]
    Stop,
    #[serde(rename = "p-kick")]
    Kick { id: String },
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct PartySummary {
    pub code: String,
    pub title: String,
    pub game: String,
    pub host: String,
    pub players: u32,
    pub max: u32,
    /// "waiting" | "playing"
    pub state: String,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct PartyMember {
    pub id: String,
    pub name: String,
    pub ready: bool,
    /// Connected to the room right now (false: in the game, or between screens).
    pub online: bool,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct PartyRoom {
    pub code: String,
    pub title: String,
    pub game: String,
    pub max: u32,
    pub public: bool,
    pub state: String,
    pub host: String,
    pub members: Vec<PartyMember>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "t", rename_all_fields = "camelCase")]
pub enum PartyServer {
    #[serde(rename = "s-p-welcome")]
    Welcome { you: String },
    #[serde(rename = "s-p-rooms")]
    Rooms { rooms: Vec<PartySummary> },
    /// The room you are in, the key that re-takes your seat later, and which seat is yours.
    #[serde(rename = "s-p-room")]
    Room { room: PartyRoom, key: String, you: String },
    /// "left" | "kicked" | "closed"
    #[serde(rename = "s-p-left")]
    Left { reason: String },
    /// The host started (or you joined a room that is playing): go into the game.
    #[serde(rename = "s-p-start")]
    Start { game: String, code: String },
    #[serde(rename = "s-p-chat")]
    Chat {
        from: String,
        name: String,
        text: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        system: Option<bool>,
    },
    #[serde(rename = "s-p-error")]
    Error { code: String },
}

/// The classroom field a "build" room's world lives under (`partyFieldName`).
pub fn party_field_name(code: &str) -> String {
    format!("party:{code}")
}

// --------------------------------------------------------------------------------------- classroom

/// One block write in ABSOLUTE field coordinates: x, y, z, block id (0 = air), brick shape.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct Edit(pub i32, pub u8, pub i32, pub u8, pub u8);

/// Water held by a shaped block: x, y, z, water id or 0 (dry).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct Wet(pub i32, pub u8, pub i32, pub u8);

/// A piece of furniture: `[kind, x, y, z, turn, palette]` plus `open` (0/1) for doors and gates.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Furniture {
    pub kind: String,
    pub x: i32,
    pub y: u8,
    pub z: i32,
    pub turn: u8,
    pub palette: u8,
    pub open: Option<u8>,
}

impl Serialize for Furniture {
    fn serialize<S: Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        let mut seq = s.serialize_seq(Some(if self.open.is_some() { 7 } else { 6 }))?;
        seq.serialize_element(&self.kind)?;
        seq.serialize_element(&self.x)?;
        seq.serialize_element(&self.y)?;
        seq.serialize_element(&self.z)?;
        seq.serialize_element(&self.turn)?;
        seq.serialize_element(&self.palette)?;
        if let Some(open) = self.open {
            seq.serialize_element(&open)?;
        }
        seq.end()
    }
}

impl<'de> Deserialize<'de> for Furniture {
    fn deserialize<D: Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        struct V;
        impl<'de> Visitor<'de> for V {
            type Value = Furniture;
            fn expecting(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
                f.write_str("[kind, x, y, z, turn, palette, open?]")
            }
            fn visit_seq<A: SeqAccess<'de>>(self, mut a: A) -> Result<Furniture, A::Error> {
                let need = |i| de::Error::invalid_length(i, &"6 or 7 elements");
                let out = Furniture {
                    kind: a.next_element()?.ok_or_else(|| need(0))?,
                    x: a.next_element()?.ok_or_else(|| need(1))?,
                    y: a.next_element()?.ok_or_else(|| need(2))?,
                    z: a.next_element()?.ok_or_else(|| need(3))?,
                    turn: a.next_element()?.ok_or_else(|| need(4))?,
                    palette: a.next_element()?.ok_or_else(|| need(5))?,
                    open: a.next_element()?,
                };
                if a.next_element::<de::IgnoredAny>()?.is_some() {
                    return Err(de::Error::invalid_length(8, &"6 or 7 elements"));
                }
                Ok(out)
            }
        }
        d.deserialize_seq(V)
    }
}

/// `heldItem` is `null` (hands empty) or absent (unchanged / older client): two different things.
mod double_option {
    use serde::{Deserialize, Deserializer, Serialize, Serializer};
    pub fn serialize<S: Serializer>(v: &Option<Option<String>>, s: S) -> Result<S::Ok, S::Error> {
        match v {
            Some(inner) => inner.serialize(s),
            None => s.serialize_none(),
        }
    }
    pub fn deserialize<'de, D: Deserializer<'de>>(d: D) -> Result<Option<Option<String>>, D::Error> {
        Ok(Some(Option::deserialize(d)?))
    }
}

/// How a player looks right now (presentationShape in classroom.ts). Everything is optional: a
/// missing field is the plain mascot doing nothing.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Presentation {
    #[serde(default, skip_serializing_if = "Option::is_none", with = "double_option")]
    pub held_item: Option<Option<String>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub tool_option: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub tool_phase: Option<f64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub action: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub action_seq: Option<u32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub action_loop: Option<bool>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub swimming: Option<bool>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub character: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub emote: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub emote_seq: Option<u32>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ClassSettings {
    pub chat_locked: bool,
    pub build_locked: bool,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub taps_locked: Option<bool>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ClassMember {
    pub id: String,
    pub name: String,
    /// "teacher" | "student"
    pub role: String,
    pub online: bool,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SnapPlayer {
    pub id: String,
    pub pos: [f64; 3],
    pub yaw: f64,
    pub anim: String,
    /// Server clock (ms) when this position arrived.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub at: Option<f64>,
    #[serde(flatten)]
    pub look: Presentation,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "t", rename_all_fields = "camelCase")]
pub enum ClassClient {
    /// Open (or, with the host key from a previous welcome, re-take) a class.
    #[serde(rename = "k-host")]
    Host {
        v: u32,
        room: String,
        teacher: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        password: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        host_key: Option<String>,
    },
    #[serde(rename = "k-join")]
    Join {
        v: u32,
        room: String,
        student: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        seat_key: Option<String>,
    },
    /// "Whose class is this?" — answered with `s-k-room`, then the socket closes.
    #[serde(rename = "k-peek")]
    Peek { v: u32, room: String },
    #[serde(rename = "k-move")]
    Move {
        pos: [f64; 3],
        yaw: f64,
        anim: String,
        /// The sender's clock (ms) when it measured `pos`.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        ct: Option<f64>,
        #[serde(flatten)]
        look: Presentation,
    },
    #[serde(rename = "k-edit")]
    Edit { edits: Vec<Edit> },
    #[serde(rename = "k-furniture")]
    Furniture { placed: Vec<Furniture>, removed: Vec<Furniture> },
    #[serde(rename = "k-chat")]
    Chat { text: String },
    #[serde(rename = "k-bonk")]
    Bonk {
        #[serde(default, skip_serializing_if = "Option::is_none")]
        target: Option<String>,
        yaw: f64,
        pitch: f64,
        seq: u32,
    },
    #[serde(rename = "k-kick")]
    Kick { player_id: String },
    #[serde(rename = "k-gather")]
    Gather,
    /// Seat the online students in rows in front of the teacher (15 × 20 cell area).
    #[serde(rename = "k-arrange")]
    Arrange {
        #[serde(default, skip_serializing_if = "Option::is_none")]
        clear: Option<bool>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        yaw: Option<f64>,
    },
    #[serde(rename = "k-settings")]
    Settings {
        chat_locked: bool,
        build_locked: bool,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        taps_locked: Option<bool>,
    },
    #[serde(rename = "k-end")]
    End,
    #[serde(rename = "k-reset-world")]
    ResetWorld,
}

/// One seat of a classroom seating: whose it is, where (absolute) and which way it faces.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SeatSign {
    pub name: String,
    pub pos: [f64; 3],
    pub yaw: f64,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "t", rename_all_fields = "camelCase")]
pub enum ClassServer {
    #[serde(rename = "s-k-welcome")]
    Welcome {
        you: String,
        role: String,
        room: String,
        teacher: String,
        /// Teacher: proves ownership on reconnect. Student: keeps the seat.
        key: String,
        members: Vec<ClassMember>,
        settings: ClassSettings,
        /// How many edits follow in `s-k-world` batches (the loading bar's total).
        edit_count: u32,
        furniture: Vec<Furniture>,
        /// Seconds within which the server always sends something.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        keepalive: Option<f64>,
    },
    #[serde(rename = "s-k-furniture")]
    Furniture {
        furniture: Vec<Furniture>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        rejected: Option<bool>,
    },
    /// Answer to `k-peek`. `exists`: saved or live; `open`: a student may join now.
    #[serde(rename = "s-k-room")]
    Room {
        room: String,
        exists: bool,
        open: bool,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        teacher: Option<String>,
    },
    #[serde(rename = "s-k-world")]
    World { edits: Vec<Edit> },
    #[serde(rename = "s-k-world-reset")]
    WorldReset,
    #[serde(rename = "s-k-members")]
    Members { members: Vec<ClassMember> },
    #[serde(rename = "s-k-snap")]
    Snap {
        #[serde(default, skip_serializing_if = "Option::is_none")]
        ts: Option<f64>,
        players: Vec<SnapPlayer>,
    },
    #[serde(rename = "s-k-edit")]
    Edit { by: String, edits: Vec<Edit> },
    #[serde(rename = "s-k-wet")]
    Wet { cells: Vec<Wet> },
    #[serde(rename = "s-k-chat")]
    Chat {
        from: String,
        name: String,
        role: String,
        text: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        system: Option<bool>,
    },
    /// With `yaw` an exact seat facing that way; without, fan out around `pos` (gather).
    #[serde(rename = "s-k-gather")]
    Gather {
        pos: [f64; 3],
        #[serde(default, skip_serializing_if = "Option::is_none")]
        yaw: Option<f64>,
    },
    /// The class's seating (dividers + name signs); empty clears it.
    #[serde(rename = "s-k-seats")]
    Seats { seats: Vec<SeatSign> },
    #[serde(rename = "s-k-bonk")]
    Bonk { by: String, target: String, seq: u32, vx: f64, vz: f64, vy: f64, at: [f64; 3] },
    #[serde(rename = "s-k-settings")]
    Settings { settings: ClassSettings },
    /// Your edit was refused: put these cells back.
    #[serde(rename = "s-k-reject")]
    Reject {
        edits: Vec<Edit>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        authoritative: Option<bool>,
    },
    #[serde(rename = "s-k-kicked")]
    Kicked,
    #[serde(rename = "s-k-closed")]
    Closed,
    #[serde(rename = "s-k-error")]
    Error { code: String },
}

/// A server message off the wire. `None` for anything oversized or malformed (one bad message is
/// skipped, never the end of the session) — the same contract as `decodeClassServer`.
pub fn decode<T: for<'de> Deserialize<'de>>(raw: &str) -> Option<T> {
    if raw.len() > MAX_SERVER_MESSAGE {
        return None;
    }
    serde_json::from_str(raw).ok()
}

pub fn encode<T: Serialize>(msg: &T) -> String {
    // every type here serialises infallibly (no maps with non-string keys, no failing impls)
    serde_json::to_string(msg).unwrap_or_default()
}

/// Class names (and people's names) match case- and space-insensitively (`classKey`).
pub fn class_key(name: &str) -> String {
    name.split_whitespace().collect::<Vec<_>>().join(" ").to_lowercase()
}
